package worker

import (
	"crypto/tls"
	"crypto/x509"
	"encoding/pem"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"sync"
	"time"
)

// CertPool manages trusted certificates for webhook delivery
type CertPool struct {
	mu       sync.RWMutex
	pool     *x509.CertPool
	revoked  map[string]bool
	updatedAt time.Time
}

var globalPool = &CertPool{
	revoked: make(map[string]bool),
}

func init() {
	globalPool.pool = x509.NewCertPool()
	loadSystemCerts()
}

func loadSystemCerts() {
	sysCerts, err := x509.SystemCertPool()
	if err != nil {
		log.Printf("warning: could not load system certs: %v", err)
		return
	}
	globalPool.pool = sysCerts
	globalPool.updatedAt = time.Now()
}

// RefreshCRL updates the certificate revocation list
func RefreshCRL(crlEndpoint string) error {
	globalPool.mu.Lock()
	defer globalPool.mu.Unlock()

	resp, err := http.Get(crlEndpoint)
	if err != nil {
		return fmt.Errorf("fetching CRL: %w", err)
	}
	defer resp.Body.Close()

	data, err := io.ReadAll(io.LimitReader(resp.Body, 10*1024*1024))
	if err != nil {
		return fmt.Errorf("reading CRL: %w", err)
	}

	crl, err := x509.ParseRevocationList(data)
	if err != nil {
		return fmt.Errorf("parsing CRL: %w", err)
	}

	for _, entry := range crl.RevokedCertificateEntries {
		globalPool.revoked[entry.SerialNumber.String()] = true
	}
	globalPool.updatedAt = time.Now()
	return nil
}

// JobPayload represents a user-uploaded webhook configuration
type JobPayload struct {
	WebhookURL    string `json:"webhook_url"`
	CustomCACert  string `json:"custom_ca_cert"`
	PayloadBody   []byte `json:"payload_body"`
	RetryCount    int    `json:"retry_count"`
	SkipDefaultCA bool   `json:"skip_default_ca"`
}

// buildTLSConfig constructs TLS configuration for webhook delivery
func buildTLSConfig(job *JobPayload) (*tls.Config, error) {
	tlsConfig := &tls.Config{
		MinVersion: tls.VersionTLS12,
	}

	// If user provides a custom CA, build a restricted pool
	if job.CustomCACert != "" {
		customPool := x509.NewCertPool()

		block, _ := pem.Decode([]byte(job.CustomCACert))
		if block == nil {
			return nil, fmt.Errorf("invalid PEM in custom_ca_cert")
		}

		cert, err := x509.ParseCertificate(block.Bytes)
		if err != nil {
			return nil, fmt.Errorf("parsing custom CA: %w", err)
		}

		if !cert.IsCA {
			return nil, fmt.Errorf("provided certificate is not a CA")
		}

		if cert.NotAfter.Before(time.Now()) {
			return nil, fmt.Errorf("custom CA certificate has expired")
		}

		customPool.AddCert(cert)

		// Merge with system pool unless explicitly skipped
		if !job.SkipDefaultCA {
			globalPool.mu.RLock()
			mergedPool := globalPool.pool.Clone()
			globalPool.mu.RUnlock()
			mergedPool.AddCert(cert)
			tlsConfig.RootCAs = mergedPool
		} else {
			tlsConfig.RootCAs = customPool
		}

		// Apply custom verification that checks revocation
		tlsConfig.VerifyPeerCertificate = makeVerifier(customPool)
	} else {
		globalPool.mu.RLock()
		tlsConfig.RootCAs = globalPool.pool.Clone()
		globalPool.mu.RUnlock()
		tlsConfig.VerifyPeerCertificate = makeVerifier(nil)
	}

	return tlsConfig, nil
}

// makeVerifier returns a verification function that checks revocation status
func makeVerifier(additionalPool *x509.CertPool) func([][]byte, [][]*x509.Certificate) error {
	return func(rawCerts [][]byte, verifiedChains [][]*x509.Certificate) error {
		globalPool.mu.RLock()
		defer globalPool.mu.RUnlock()

		for _, chain := range verifiedChains {
			for _, cert := range chain {
				serial := cert.SerialNumber.String()
				if globalPool.revoked[serial] {
					return fmt.Errorf("certificate %s is revoked", serial)
				}
			}
		}
		return nil
	}
}

// ProcessWebhookJob handles the background delivery of a webhook
func ProcessWebhookJob(job *JobPayload) error {
	if job.WebhookURL == "" {
		return fmt.Errorf("webhook_url is required")
	}

	tlsConfig, err := buildTLSConfig(job)
	if err != nil {
		return fmt.Errorf("building TLS config: %w", err)
	}

	client := &http.Client{
		Timeout: 30 * time.Second,
		Transport: &http.Transport{
			TLSClientConfig: tlsConfig,
			MaxIdleConns:    10,
			IdleConnTimeout: 90 * time.Second,
		},
	}

	var lastErr error
	for attempt := 0; attempt <= job.RetryCount; attempt++ {
		if attempt > 0 {
			time.Sleep(time.Duration(attempt) * 2 * time.Second)
		}

		resp, err := client.Post(job.WebhookURL, "application/json", nil)
		if err != nil {
			lastErr = err
			log.Printf("attempt %d failed: %v", attempt+1, err)
			continue
		}
		resp.Body.Close()

		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
			log.Printf("webhook delivered successfully on attempt %d", attempt+1)
			return nil
		}
		lastErr = fmt.Errorf("unexpected status: %d", resp.StatusCode)
	}

	return fmt.Errorf("all attempts failed: %w", lastErr)
}

func main() {
	// Start CRL refresh goroutine
	crlURL := os.Getenv("CRL_ENDPOINT")
	if crlURL != "" {
		go func() {
			for {
				if err := RefreshCRL(crlURL); err != nil {
					log.Printf("CRL refresh error: %v", err)
				}
				time.Sleep(1 * time.Hour)
			}
		}()
	}

	log.Println("worker started")
	select {}
}
